    //          following the rules from the given logic.

    // Helper function: is_power_of_two
    // Verus spec: for any n, returns true iff n is a positive power of two
    fn is_power_of_two(n: i32) -> bool {
        // Spec:
        // ensures returns true <==> n > 0 && n is a power of two
        // i.e. exists k >= 0 :: n == 2^k
        n > 0 && (n & (n - 1)) == 0
    }

    // Helper function: is_limited_prime
    // Verus spec: returns true iff p is "limited prime" defined as:
    //    p == 2 or (p > 2 and p is odd)
    // returns false if p <= 1 or even and > 2
    fn is_limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else if p % 2 == 0 {
            false
        } else {
            true
        }
    }

    // Main specification requires (verified at runtime by implicitly trusting input):
    let t = input[0] as usize;
    // require t <= input.len() - 1 so that for i in 0..t, input[i+1] is valid

